package alphametics

import (
	"errors"
	"fmt"
	"math"
	"sort"
	"strings"
)

// Solve solves an alphametics puzzle of the form "WORD + WORD + ... == WORD".
// It returns a mapping of each letter to a distinct digit such that the
// equation holds, where the leading digit of every multi-digit word is
// non-zero. An error is returned if the puzzle has no solution.
func Solve(puzzle string) (map[string]int, error) {
	sides := strings.Split(puzzle, "==")
	if len(sides) != 2 {
		return nil, fmt.Errorf("invalid puzzle %q: expected exactly one '=='", puzzle)
	}

	// coeff accumulates the place-value weight of each letter: positive
	// for words on the left of "==", negative for words on the right. A
	// valid assignment makes the total sum exactly zero.
	coeff := make(map[rune]int64)
	leading := make(map[rune]bool)

	addWord := func(word string, sign int) {
		if word == "" {
			return
		}
		if len(word) > 1 {
			leading[word[0]] = true
		}
		place := int64(1)
		for i := len(word) - 1; i >= 0; i-- {
			coeff[word[i]] += int64(sign) * place
			place *= 10
		}
	}

	for _, w := range strings.Split(sides[0], "+") {
		addWord(strings.TrimSpace(w), 1)
	}
	for _, w := range strings.Fields(sides[1]) {
		addWord(w, -1)
	}

	if len(coeff) > 10 {
		return nil, errors.New("no solution: more than ten distinct letters")
	}

	letters := make([]rune, 0, len(coeff))
	for r := range coeff {
		letters = append(letters, r)
	}
	// Assign the letters with the largest coefficients first so that the
	// pruning below cuts off branches as early as possible.
	sort.Slice(letters, func(i, j int) bool {
		return math.Abs(coeff[letters[i]]) > math.Abs(coeff[letters[j]])
	})

	n := len(letters)
	co := make([]int64, n)
	lead := make([]bool, n)
	for i, r := range letters {
		co[i] = coeff[r]
		lead[i] = leading[r]
	}

	// minSuffix[i] / maxSuffix[i] bound how much the not-yet-assigned
	// letters (i through n-1) can still contribute to the total sum,
	// assuming each may take any digit 0-9.
	minSuffix := make([]int64, n+1)
	maxSuffix := make([]int64, n+1)
	for i := n - 1; i >= 0; i-- {
		minSuffix[i] = minSuffix[i + 1]
		maxSuffix[i] = maxSuffix[i + 1]
		if co[i] > 0 {
			maxSuffix[i] += co[i] * 9
		} else {
			minSuffix[i] += co[i] * 9
		}
	}

	assignment := make([]int, n)
	used := make([]bool, 10)

	// search assigns a digit to letters[i..n-1] given the running sum of
	// the contributions of letters[0..i-1].
	var search func(i int, sum int64) bool
	search = func(i int, sum int64) bool {
		if i == n {
			return sum == 0
		}
		// Prune if the remaining letters cannot bring the sum to zero.
		if sum+minSuffix[i] > 0 || sum+maxSuffix[i] < 0 {
			return false
		}
		start := 0
		if lead[i] {
			start = 1
		}
		for d := start; d <= 9; d++ {
			if used[d] {
				continue
			}
			used[d] = true
			assignment[i] = d
			if search(i+1, sum+co[i]*int64(d)) {
				return true
			}
			used[d] = false
		}
		return false
	}

	if !search(0, 0) {
		return nil, errors.New("no solution")
	}

	result := make(map[string]int, n)
	for i, r := range letters {
		result[string(r)] = assignment[i]
	}
	return result, nil
}

